1	"use client";
2	
3	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
4	import { gsap, prefersReducedMotion, useGSAP } from "@/lib/gsap";
5	import { getChapter, getStory } from "@/lib/api";
6	import { useReadTracker } from "@/lib/readTracker";
7	import { useReadingPosition } from "@/lib/useReadingPosition";
8	import type { ContentType } from "@/types";
9	import QuoteShare from "./QuoteShare";
10	import ReadingPrefs from "./ReadingPrefs";
11	import RichText from "./RichText";
12	import styles from "./ReadingView.module.css";
13	
14	type ReadingMode = "paged" | "infinite";
15	
16	interface Props {
17	  contentType: ContentType;
18	  contentId: string;
19	  initialContent: string;
20	  initialPage: number;
21	  totalPages: number;
22	  /** Title used in share attributions (e.g. "Part 3 — Series Name"). */
23	  shareTitle: string;
24	  /**
25	   * Canonical URL of the work, no querystring. The `?page=N` suffix
26	   * is appended internally for paginated reads so a shared quote
27	   * lands the visitor on the same page it was lifted from.
28	   */
29	  shareUrl: string;
30	}
31	
32	export default function ReadingView({
33	  contentType,
34	  contentId,
35	  initialContent,
36	  initialPage,
37	  totalPages,
38	  shareTitle,
39	  shareUrl,
40	}: Props) {
41	  const [mode, setMode] = useState<ReadingMode>("paged");
42	  const [currentPage, setCurrentPage] = useState(initialPage);
43	  const [pages, setPages] = useState<Record<number, string>>({
44	    [initialPage]: initialContent,
45	  });
46	  const [loadingPage, setLoadingPage] = useState<number | null>(null);
47	  const [progress, setProgress] = useState(0);
48	  const [scrolled, setScrolled] = useState(false);
49	
50	  const contentRef = useRef<HTMLDivElement>(null);
51	
52	  // Ref mirrors of the cache + in-flight set used by loadPage. Two
53	  // problems they solve together:
54	  //
55	  //   1. The previous version had `pages` in its useCallback deps so
56	  //      loadPage's identity churned on every fetch completion, and
57	  //      the `if (pages[n]) return` check was reading the *previous*
58	  //      render's snapshot. A second loadPage(n) racing in between
59	  //      the fetch resolve and the next render would pass that
60	  //      check and fire a duplicate request.
61	  //
62	  //   2. Even with a fresh closure, two callers (e.g. keyboard nav
63	  //      + the infinite-mode prefetch) could overlap on the SAME
64	  //      page number before either fetch resolves. State-based
65	  //      dedup can't help because nothing in state changes during
66	  //      the in-flight window.
67	  //
68	  // pagesRef is updated synchronously inside loadPage before the
69	  // setPages call, so a second call sees the latest cache without
70	  // waiting for React to commit. inFlightRef closes the overlap
71	  // window: a page number sits in the set from the moment we kick
72	  // off the fetch to the moment the cache is populated.
73	  const pagesRef = useRef<Record<number, string>>({
74	    [initialPage]: initialContent,
75	  });
76	  const inFlightRef = useRef<Set<number>>(new Set());
77	
78	  useReadTracker({ contentType, contentId });
79	
80	  // Resume-on-mount / save-on-scroll. The hook only runs in paged
81	  // mode here because infinite mode would otherwise restore a
82	  // single percentage against a much longer document, putting the
83	  // reader at a confusing point in the middle of a different page's
84	  // worth of prose. Paged mode also matches the backend's stored
85	  // `pageNumber` so the restore lands on the right page.
86	  useReadingPosition({
87	    contentType,
88	    contentId,
89	    pageNumber: mode === "paged" ? currentPage : null,
90	    enabled: mode === "paged",
91	  });
92	
93	  // Fetch a page lazily; reuse cached pages when we already have them.
94	  // Identity is stable across re-renders (deps don't include `pages`)
95	  // — the dedup logic reads from the refs above.
96	  const loadPage = useCallback(
97	    async (pageNumber: number) => {
98	      if (pagesRef.current[pageNumber]) return;
99	      if (inFlightRef.current.has(pageNumber)) return;
100	      inFlightRef.current.add(pageNumber);
101	      setLoadingPage(pageNumber);
102	      try {
103	        const fetched =
104	          contentType === "story"
105	            ? await getStory(contentId, pageNumber)
106	            : await getChapter(contentId, pageNumber);
107	        // Update the ref first (synchronously visible) and then the
108	        // state for the next render. Both writes happen before
109	        // inFlightRef releases the page number.
110	        const next = {
111	          ...pagesRef.current,
112	          [pageNumber]: fetched.content,
113	        };
114	        pagesRef.current = next;
115	        setPages(next);
116	      } finally {
117	        inFlightRef.current.delete(pageNumber);
118	        setLoadingPage(null);
119	      }
120	    },
121	    [contentId, contentType],
122	  );
123	
124	  // ── Paged-mode page change animation ──
125	  useGSAP(
126	    () => {
127	      if (mode !== "paged" || !contentRef.current) return;
128	      if (prefersReducedMotion()) return;
129	      gsap.fromTo(
130	        contentRef.current,
131	        { opacity: 0, y: 40 },
132	        { opacity: 1, y: 0, duration: 0.4, ease: "power2.out" },
133	      );
134	    },
135	    { dependencies: [mode, currentPage], scope: contentRef },
136	  );
137	
138	  // ── Progress + scroll-to-top tracking ──
139	  useEffect(() => {
140	    const onScroll = () => {
141	      const scrollY = window.scrollY;
142	      setScrolled(scrollY > 400);
143	
144	      if (mode === "paged") {
145	        // Progress = current page / total pages.
146	        setProgress(totalPages > 0 ? (currentPage / totalPages) * 100 : 0);
147	        return;
148	      }
149	
150	      // Infinite mode: scroll position relative to total scrollable height.
151	      const docHeight = document.documentElement.scrollHeight - window.innerHeight;
152	      setProgress(docHeight > 0 ? (scrollY / docHeight) * 100 : 0);
153	    };
154	    onScroll();
155	    window.addEventListener("scroll", onScroll, { passive: true });
156	    return () => window.removeEventListener("scroll", onScroll);
157	  }, [mode, currentPage, totalPages]);
158	
159	  // ── Mode toggle ──
160	  const switchToInfinite = async () => {
161	    setMode("infinite");
162	    // Pre-fetch every missing page so the stack is complete.
163	    const missing = Array.from({ length: totalPages }, (_, i) => i + 1).filter(
164	      (n) => !pages[n],
165	    );
166	    await Promise.all(missing.map(loadPage));
167	  };
168	
169	  const switchToPaged = () => {
170	    setMode("paged");
171	    window.scrollTo({ top: 0, behavior: "auto" });
172	  };
173	
174	  // ── Page navigation (paged mode) ──
175	  const goToPage = async (n: number) => {
176	    if (n < 1 || n > totalPages || n === currentPage) return;
177	    await loadPage(n);
178	    setCurrentPage(n);
179	    window.scrollTo({ top: 0, behavior: "auto" });
180	  };
181	
182	  const scrollToTop = () => {
183	    window.scrollTo({ top: 0, behavior: "smooth" });
184	  };
185	
186	  // ── Keyboard navigation ──
187	  // Arrow keys + j/k turn pages in paged mode. Skips the binding when
188	  // the user is typing in a field (search box, etc.) or holding a
189	  // modifier (Cmd+K command palette already owns Cmd/Ctrl).
190	  useEffect(() => {
191	    if (mode !== "paged" || totalPages <= 1) return;
192	    const onKey = (e: KeyboardEvent) => {
193	      if (e.metaKey || e.ctrlKey || e.altKey) return;
194	      const target = e.target as HTMLElement | null;
195	      if (target) {
196	        const tag = target.tagName;
197	        if (
198	          tag === "INPUT" ||
199	          tag === "TEXTAREA" ||
200	          tag === "SELECT" ||
201	          target.isContentEditable
202	        ) {
203	          return;
204	        }
205	      }
206	      if (e.key === "ArrowRight" || e.key === "j" || e.key === "l") {
207	        e.preventDefault();
208	        void goToPage(currentPage + 1);
209	      } else if (e.key === "ArrowLeft" || e.key === "k" || e.key === "h") {
210	        e.preventDefault();
211	        void goToPage(currentPage - 1);
212	      }
213	    };
214	    window.addEventListener("keydown", onKey);
215	    return () => window.removeEventListener("keydown", onKey);
216	    // eslint-disable-next-line react-hooks/exhaustive-deps
217	  }, [mode, currentPage, totalPages]);
218	
219	  // ── Render ──
220	  const isLoading = loadingPage !== null;
221	
222	  // Page-aware share URL — only append `?page=N` for N>1 so a quote
223	  // selected on page 1 doesn't pick up redundant querystring noise.
224	  // In infinite mode there's no single page, so we drop the suffix
225	  // and let the polyfill / browser handle scrolling.
226	  const effectiveShareUrl = useMemo(() => {
227	    if (mode !== "paged") return shareUrl;
228	    if (currentPage <= 1) return shareUrl;
229	    const sep = shareUrl.includes("?") ? "&" : "?";
230	    return `${shareUrl}${sep}page=${currentPage}`;
231	  }, [shareUrl, mode, currentPage]);
232	
233	  return (
234	    <div className={styles.wrapper}>
235	      {/* Floating share popover anchored to text selections inside
236	          the content div. Scoped to `contentRef` so selections in
237	          the page header / footer don't trigger it. */}
238	      <QuoteShare
239	        title={shareTitle}
240	        url={effectiveShareUrl}
241	        containerRef={contentRef}
242	      />
243	      {/* Sticky progress bar */}
244	      <div className={styles.progressBar} aria-hidden="true">
245	        <div
246	          className={styles.progressFill}
247	          style={{ width: `${Math.min(Math.max(progress, 0), 100)}%` }}
248	        />
249	      </div>
250	
251	      {/* Reader controls — mode toggle (only when there's more than
252	          one page) and reading prefs (always visible, so font size /
253	          column width / WPM are reachable on short pieces too). */}
254	      <div className={styles.controlsRow}>
255	        {totalPages > 1 && (
256	          <div className={styles.modeToggle} role="tablist" aria-label="Reading mode">
257	            <button
258	              type="button"
259	              role="tab"
260	              aria-selected={mode === "paged"}
261	              onClick={switchToPaged}
262	              className={`${styles.modeButton} ${mode === "paged" ? styles.modeButtonActive : ""}`}
263	            >
264	              <DocIcon />
265	              Pages
266	            </button>
267	            <button
268	              type="button"
269	              role="tab"
270	              aria-selected={mode === "infinite"}
271	              onClick={switchToInfinite}
272	              className={`${styles.modeButton} ${mode === "infinite" ? styles.modeButtonActive : ""}`}
273	            >
274	              <ScrollIcon />
275	              Scroll
276	            </button>
277	          </div>
278	        )}
279	        <ReadingPrefs />
280	      </div>
281	
282	      {/* Content */}
283	      <div ref={contentRef} className={`reading-content ${styles.content}`}>
284	        {mode === "paged" ? (
285	          isLoading && !pages[currentPage] ? (
286	            <p style={{ color: "var(--text-muted)" }}>Loading…</p>
287	          ) : (
288	            <RichText content={pages[currentPage] ?? ""} />
289	          )
290	        ) : (
291	          Array.from({ length: totalPages }, (_, i) => i + 1).map((n, idx) => (
292	            <div key={n}>
293	              {pages[n] ? (
294	                <RichText content={pages[n]} />
295	              ) : (
296	                <p style={{ color: "var(--text-muted)" }}>Loading page {n}…</p>
297	              )}
298	              {idx < totalPages - 1 && <hr className={styles.divider} />}
299	            </div>
300	          ))
301	        )}
302	      </div>
303	
304	      {/* Off-screen live region that announces page changes to
305	          screen readers. `aria-live="polite"` waits for the user
306	          to finish whatever they're hearing before speaking. The
307	          visible page buttons below have aria-current="page", which
308	          announces the change but doesn't volunteer the *new* page
309	          number after a click — this fills that gap. */}
310	      <div
311	        className={styles.visuallyHidden}
312	        aria-live="polite"
313	        aria-atomic="true"
314	      >
315	        {mode === "paged" && totalPages > 1
316	          ? `Page ${currentPage} of ${totalPages}`
317	          : ""}
318	      </div>
319	
320	      {/* Pagination (paged mode only) */}
321	      {mode === "paged" && totalPages > 1 && (
322	        <nav className={styles.pagination} aria-label="Page navigation">
323	          <button
324	            type="button"
325	            onClick={() => goToPage(currentPage - 1)}
326	            disabled={currentPage <= 1 || isLoading}
327	            className={styles.pageButton}
328	            aria-label="Previous page"
329	          >
330	            ←
331	          </button>
332	          {Array.from({ length: totalPages }, (_, i) => i + 1).map((n) => (
333	            <button
334	              key={n}
335	              type="button"
336	              onClick={() => goToPage(n)}
337	              disabled={isLoading}
338	              className={`${styles.pageButton} ${
339	                n === currentPage ? styles.pageButtonActive : ""
340	              }`}
341	              aria-current={n === currentPage ? "page" : undefined}
342	            >
343	              {n}
344	            </button>
345	          ))}
346	          <button
347	            type="button"
348	            onClick={() => goToPage(currentPage + 1)}
349	            disabled={currentPage >= totalPages || isLoading}
350	            className={styles.pageButton}
351	            aria-label="Next page"
352	          >
353	            →
354	          </button>
355	        </nav>
356	      )}
357	
358	      {/* Scroll-to-top */}
359	      <button
360	        type="button"
361	        onClick={scrollToTop}
362	        aria-label="Scroll to top"
363	        className={`${styles.scrollTop} ${scrolled ? styles.scrollTopVisible : ""}`}
364	      >
365	        <UpIcon />
366	      </button>
367	    </div>
368	  );
369	}
370	
371	// ── Helpers ────────────────────────────────────────────────────────
372	
373	function DocIcon() {
374	  return (
375	    <svg className={styles.modeIcon} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" suppressHydrationWarning>
376	      <path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z" />
377	      <polyline points="14 3 14 9 20 9" />
378	    </svg>
379	  );
380	}
381	
382	function ScrollIcon() {
383	  return (
384	    <svg className={styles.modeIcon} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" suppressHydrationWarning>
385	      <path d="M3 8a4 4 0 1 1 8 0v8a4 4 0 1 0 8 0v-1" />
386	      <path d="M11 8h8" />
387	    </svg>
388	  );
389	}
390	
