219	/** Binary-search the node containing `offset` in the combined text. */
220	function locate(
221	  nodes: Text[],
222	  starts: number[],
223	  offset: number,
224	): NodeLocation | null {
225	  if (nodes.length === 0) return null;
226	  let lo = 0;
227	  let hi = nodes.length - 1;
228	  while (lo < hi) {
229	    const mid = (lo + hi + 1) >>> 1;
230	    if (starts[mid] <= offset) lo = mid;
231	    else hi = mid - 1;
232	  }
233	  const node = nodes[lo];
